    },
    {
      "claim": "After the change, orders started timing out calls to payments after about 6 ms.",
      "status": "confirmed",
      "cites": ["orders-S00e73", "orders-S00e76", "orders-S00e78"]
    },
    {
      "claim": "Orders retried the failing payment calls many times with little or no backoff.",
      "status": "confirmed",
      "cites": ["orders-S00e7d", "orders-S00e7f", "orders-S00e80"]
    },
    {
      "claim": "The resulting overload caused orders to return errors to the gateway, which observed upstream_timeout on entry requests.",
      "status": "uncertain",
      "cites": ["gateway-S0099e"]
    }
  ],
